#include <ptlib.h>
#include <ptlib/pprocess.h>
#include <codec/vidcodec.h>
#include <sdp/sdp.h>
#include <h323/h323caps.h>
#include <asn/h245.h>
#include "../VideoPreferences.h"
#include <iostream>
class Process : public PProcess {PCLASSINFO(Process,PProcess);public:Process():PProcess("MyStudio","VideoCaps",1,0,ReleaseCode,0){}void Main()override{}};
void Require(bool value,const char*message){if(!value)throw std::runtime_error(message);}
void PeerBandwidthFallback(){
 OpalMediaFormat local(OpalH264);local.SetOptionString(OpalMediaFormat::ProtocolOption(),"SIP");
 studio::opal::ConfigureVideoFormat(local,1920,1080,4000,30);
 Require(local.ToCustomisedOptions(),"Preferred1080p4Mbps customisation failed");
 SDPSessionDescription offer(1,1,OpalTransportAddress("udp$127.0.0.1:5000"));
 auto*video=new SDPVideoMediaDescription(OpalTransportAddress("udp$127.0.0.1:5000"));video->AddMediaFormat(local);offer.AddMediaDescription(video);
 Require(offer.Encode().Find("b=AS:4000")!=P_MAX_INDEX&&offer.Encode().Find("b=TIAS:4000000")!=P_MAX_INDEX,"Preferred4Mbps SDP bandwidth absent");
 OpalMediaFormatList supported;supported+=local;
 SDPSessionDescription peer(0,0,OpalTransportAddress("udp$127.0.0.1:5002"));
 Require(peer.Decode(PString("v=0\r\no=- 2 2 IN IP4 127.0.0.1\r\ns=Constrained peer\r\nc=IN IP4 127.0.0.1\r\nt=0 0\r\nm=video 5002 RTP/AVP 99\r\nb=AS:1500\r\nb=TIAS:1500000\r\na=rtpmap:99 H264/90000\r\na=fmtp:99 packetization-mode=1;profile-level-id=42001f;max-fs=3600;max-mbps=108000;max-br=1500\r\n"),supported),"Constrained720p1.5Mbps SDP rejected");
 auto formats=peer.GetMediaFormats();Require(formats.GetSize()>0&&local.Merge(formats[0])&&local.ToNormalisedOptions(),"Constrained peer negotiation merge failed");
 Require(local.GetOptionInteger(OpalVideoFormat::FrameWidthOption())<=1280&&local.GetOptionInteger(OpalVideoFormat::FrameHeightOption())<=720,"Remote720p dimensions ignored");
 Require(local.GetOptionInteger(OpalMediaFormat::TargetBitRateOption())<=1500000&&local.GetOptionInteger(OpalMediaFormat::MaxBitRateOption())<=1500000,"Remote1.5Mbps bandwidth ignored");
 std::cout<<"Preferred1080p4Mbps -> peer720p1.5Mbps negotiated fallback PASS\n";
}
void SonyMode0(){OpalMediaFormat mode0(OpalH264_MODE0);mode0.SetOptionString(OpalMediaFormat::ProtocolOption(),"SIP");studio::opal::ConfigureVideoFormat(mode0,1920,1080,4000,30);Require(mode0.ToCustomisedOptions(),"Sony mode0 customisation failed");OpalMediaFormatList supported;supported+=mode0;SDPSessionDescription answer(0,0,OpalTransportAddress("udp$127.0.0.1:49154"));Require(answer.Decode(PString("v=0\r\no=- 1 1 IN IP4 127.0.0.1\r\ns=Sony TC7.3.3 fixture\r\nc=IN IP4 127.0.0.1\r\nt=0 0\r\nm=video 49154 RTP/AVP 98\r\na=rtpmap:98 H264/90000\r\na=fmtp:98 profile-level-id=42c01f;max-mbps=108000;max-fs=3840;max-br=2048\r\n"),supported),"Sony AVP mode0 SDP decode failed");auto formats=answer.GetMediaFormats();Require(formats.GetSize()>0&&formats[0].GetName()==mode0.GetName(),"Sony omitted packetization-mode did not select mode0");Require(mode0.Merge(formats[0])&&mode0.ToNormalisedOptions()&&mode0.GetOptionInteger(OpalVideoFormat::FrameWidthOption())==1280&&mode0.GetOptionInteger(OpalVideoFormat::FrameHeightOption())==720,"Sony mode0 720p negotiation failed");std::cout<<"Exact Sony mode0 answer720p AVP negotiation PASS\n";}
int main(){_putenv_s("PTLIBPLUGINDIR","MyStudio-no-auto-plugins");Process process;try{PeerBandwidthFallback();SonyMode0();OpalMediaFormat full(OpalH264);full.SetOptionString(OpalMediaFormat::ProtocolOption(),"SIP");studio::opal::ConfigureVideoFormat(full,1920,1080,4000,30);Require(full.ToCustomisedOptions(),"1080p H264 customisation failed");SDPSessionDescription sdp(1,1,OpalTransportAddress("udp$127.0.0.1:5000"));auto*video=new SDPVideoMediaDescription(OpalTransportAddress("udp$127.0.0.1:5000"));video->AddMediaFormat(full);sdp.AddMediaDescription(video);auto wire=sdp.Encode();std::cout<<wire;Require(wire.Find("max-fs=8160")!=P_MAX_INDEX&&wire.Find("max-mbps=244800")!=P_MAX_INDEX,"Initial SDP does not advertise actual1080p30 limits");SDPSessionDescription received(0,0,OpalTransportAddress("udp$127.0.0.1:5000"));OpalMediaFormatList supported;supported+=full;Require(received.Decode(wire,supported),"1080p SDP decode failed");auto formats=received.GetMediaFormats();Require(formats.GetSize()>0,"1080p SDP had no supported format");auto merged=full;Require(merged.Merge(formats[0])&&merged.ToNormalisedOptions(),"1080p negotiation merge failed");std::cout<<"Merged "<<merged.GetOptionInteger(OpalVideoFormat::FrameWidthOption())<<"x"<<merged.GetOptionInteger(OpalVideoFormat::FrameHeightOption())<<" maxRx="<<merged.GetOptionInteger(OpalVideoFormat::MaxRxFrameWidthOption())<<"x"<<merged.GetOptionInteger(OpalVideoFormat::MaxRxFrameHeightOption())<<" FrameTime="<<merged.GetFrameTime()<<"\n";Require(merged.GetOptionInteger(OpalVideoFormat::FrameWidthOption())==1920&&merged.GetOptionInteger(OpalVideoFormat::FrameHeightOption())==1080,"1080p SDP downgraded unexpectedly");SDPSessionDescription lower(0,0,OpalTransportAddress("udp$127.0.0.1:5000"));Require(lower.Decode(PString("v=0\r\no=- 2 2 IN IP4 127.0.0.1\r\ns=fixture\r\nc=IN IP4 127.0.0.1\r\nt=0 0\r\nm=video 5000 RTP/AVP 98\r\na=rtpmap:98 H264/90000\r\na=fmtp:98 packetization-mode=1;profile-level-id=42001f\r\n"),supported),"Lower-level SDP decode failed");auto lowerFormats=lower.GetMediaFormats();auto limited=full;Require(lowerFormats.GetSize()>0&&limited.Merge(lowerFormats[0])&&limited.ToNormalisedOptions(),"Lower-level H264 merge failed");Require(limited.GetOptionInteger(OpalVideoFormat::FrameWidthOption())<=1280&&limited.GetOptionInteger(OpalVideoFormat::FrameHeightOption())<=720,"Peer720p limit was ignored");OpalMediaFormat h323(full);h323.SetOptionString(OpalMediaFormat::ProtocolOption(),"H.323");std::unique_ptr<H323Capability> sender(H323Capability::Create(full.GetName())),receiver(H323Capability::Create(full.GetName()));Require(sender&&receiver,"H264 H245 capability unavailable");Require(sender->UpdateMediaFormat(h323),"H264 H245 configuration failed");auto*generic=dynamic_cast<H323GenericVideoCapability*>(sender.get());Require(generic!=nullptr,"H264 generic video capability unavailable");H245_VideoCapability tcs;Require(generic->OnSendingPDU(tcs,H323Capability::e_TCS),"H264 TCS generation failed");auto*rx=dynamic_cast<H323GenericVideoCapability*>(receiver.get());Require(rx&&rx->OnReceivedPDU(tcs,H323Capability::e_TCS),"H264 TCS decode failed");auto negotiated=receiver->GetMediaFormat();Require(negotiated.ToNormalisedOptions()&&negotiated.GetOptionInteger(OpalVideoFormat::MaxRxFrameWidthOption())>=1920&&negotiated.GetOptionInteger(OpalVideoFormat::MaxRxFrameHeightOption())>=1080,"H245 capability cannot retain1080p");std::cout<<"H2641080p SDP/H245 negotiation and720p fallback PASS\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
